import { Component, isDevMode } from '@angular/core';
import { bootstrapApplication } from '@angular/platform-browser';
import { provideRouter, RouterOutlet } from '@angular/router';
import { provideHttpClient } from '@angular/common/http';
import { routes } from './app/app.routes';
import { Configuration } from './generated/api';
import { environment } from './environments/environment';
import { provideServiceWorker } from '@angular/service-worker';
import { DATA_REPOSITORY } from "./app/database/data-repository";
import { DexieDataBase } from "./app/database/dexie/dexie-data-base.service";

// Configure OpenAPI client
const apiConfiguration = new Configuration({
  basePath: environment.apiUrl,
  credentials: {
    OAuth2: () => localStorage.getItem('authToken') || undefined
  },
});

@Component({
  selector: 'lok-root',
  imports: [RouterOutlet],
  template: '<router-outlet />'
})
export class App {
}

bootstrapApplication(App, {
  providers: [
    provideRouter(routes),
    provideHttpClient(),
    {provide: Configuration, useValue: apiConfiguration},
    provideServiceWorker('ngsw-worker.js', {
      enabled: !isDevMode(),
      registrationStrategy: 'registerImmediately'
    }),
    {provide: DATA_REPOSITORY, useClass: DexieDataBase}
  ]
}).catch(err => console.error(err));
